import os
import stripe
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('notes-kb')
stripe.api_key = os.environ['STRIPE_API_KEY']
PACK_PRICES_CENTS = {'pack_research': 1900, 'pack_meeting': 900, 'pack_zettel': 1400}

def _price_for(pack_id: str, quantity: int) -> int:
    if pack_id not in PACK_PRICES_CENTS:
        raise ValueError(f'Unknown template pack: {pack_id}')
    if quantity < 1:
        raise ValueError('quantity must be at least 1')
    return PACK_PRICES_CENTS[pack_id] * quantity

@mcp.tool()
def purchase_premium_template_pack(pack_id: str, customer_id: str, quantity: int=1) -> dict:
    amount = _price_for(pack_id, quantity)
    # Cancel stale unconfirmed payment intents for the same pack so duplicates don't linger
    for stale in stripe.PaymentIntent.list(customer=customer_id, limit=20).data:
        if stale.status in ('requires_payment_method', 'requires_confirmation', 'requires_action') and stale.metadata.get('pack_id') == pack_id:
            stripe.PaymentIntent.cancel(stale.id)
    intent = stripe.PaymentIntent.create(amount=amount, currency='usd', customer=customer_id, confirm=True, off_session=True, description=f'Template pack {pack_id} x{quantity}', metadata={'pack_id': pack_id, 'quantity': str(quantity)})
    return {'payment_id': intent.id, 'status': intent.status, 'amount_cents': amount}
